import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { Helmet } from 'react-helmet-async';
import { Stack, Typography, Card, Grid, Button } from '@mui/material';
import { axios } from '../utils/axios';
import { useMyContext } from "./provider";
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import GoBackButton from '../components/goBackButton/GoBackButton';
import InputField from '../components/input/inputField';
import useResponsive from "../hooks/useResponsive";

export default function CommissionAndTax() {
    const navigate = useNavigate();
    const location = useLocation();
    const [commission, setCommission] = useState('')
    const [tax, setTax] = useState('')
    const [data, setData] = useState('')
    const isAddButtonDisabled = !tax || !commission;
    const { i18 } = useMyContext();
    const isMobile = useResponsive("down", "sm");
    const { id, name } = location?.state || { id: '', name: '' };
    const backtouser = () => {
        navigate('/dashboard/listing')
    }
    const handlePost = async () => {
        try {
            const Data = {
                commission,
                tax,
                status: 'active'
            }
            const res = await axios.post(`/module/listing/comisionAndTax?listingId=${id}`, Data)
            if (res.status === 200) {
                GenerateToastConfig(res.data.message, 'success');
                backtouser()
                fetchData()
            }
            else {
                GenerateToastConfig(res.data.message);
            }
        }
        catch (err) {
            GenerateToastConfig(err?.response?.data?.message);
        }
    }

    const fetchData = async () => {

        const res = await axios.get(`module/listing/comisionAndTax?listingId=${id}`);
        if (res.status === 200 && res?.data?.data?.comisionAndTax) {
            setData(res?.data?.data);
            setCommission(res?.data?.data?.comisionAndTax[0]?.commission.toString())
            setTax(res?.data?.data?.comisionAndTax[0]?.tax.toString())
        }
    }
    useEffect(() => {
        fetchData()
    }, [])

    return (
        <>
            <Helmet>
                <title> {i18?.LISTINGPAGE?.COMMISSION_TAX || "Commission & Tax"} </title>
            </Helmet>
            <Stack direction="row" alignItems="center" justifyContent="space-between" mb={5}>
                <Typography variant="h4" gutterBottom>
                    {name.toUpperCase()}
                </Typography>
            </Stack>
            <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
                <Grid container sx={{ borderBottom: '1px solid #dbe0e4', padding: '10px 0px' }}>
                    <Grid container item xs={12} sm={6} justifyContent="flex-start" alignItems="center" sx={{ marginBottom: { xs: '10px', sm: '0px' } }}>
                        <Typography variant="h6" gutterBottom sx={{ marginLeft: { sm: '3px' }, paddingBottom: '0px' }}>
                            {i18?.LISTINGPAGE?.COMMISSION_TAX || "Commission & Tax"}
                        </Typography>
                    </Grid>
                    <Grid container item xs={12} sm={6} justifyContent={{ xs: 'center', sm: 'flex-end' }} alignItems="center">
                        <GoBackButton
                            label={i18?.LISTINGPAGE?.GO_BACK || "Go Back"}
                            onClick={backtouser}
                            icon="icon-park-twotone:back"
                        />
                    </Grid>
                </Grid>
                <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
                    <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                        <InputField
                            label={i18?.LISTINGPAGE?.COMMISSION || "Commission"}
                            sx={{ margin: '10px 0px', width: '100%' }}
                            name="FirstName"
                            value={commission}
                            onChange={(e) => setCommission(e.target.value)}
                        />
                    </Grid>
                    <Grid item xs={6} sx={{ padding: '0px 5px' }}>
                        <InputField
                            label={i18?.LISTINGPAGE?.TAX || "Tax"}
                            sx={{ margin: '10px 0px', width: '100%' }}
                            name="FirstName"
                            value={tax}
                            onChange={(e) => setTax(e.target.value)}
                        />
                    </Grid>
                </Grid>
                <Grid container justifyContent="flex-end" sx={{ paddingRight: '20px', bottom: '10px' }}>
                    <Button variant="contained" disabled={isAddButtonDisabled} onClick={handlePost}>
                        {i18?.LISTINGPAGE?.ADD || "Add"}
                    </Button>
                </Grid>
            </Card>
        </>
    )
}